<!doctype html>
<html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Painel administrativo | Veste+</title>
<style>body{font:15px system-ui;background:#f3f6f4;margin:0;color:#17332b}.top{background:#fff;padding:18px 5vw;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e1e9e4}.top a{color:#19734f}.wrap{max-width:1180px;margin:28px auto;padding:0 20px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.card,section{background:white;padding:18px;border-radius:12px;box-shadow:0 4px 16px #18352b0b}.card strong{font-size:30px;display:block;color:#19734f}section{margin-top:20px;overflow:auto}table{border-collapse:collapse;width:100%;min-width:600px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e8eeea}th{color:#51665d;background:#f8faf9}.muted{color:#6a7c73}</style></head>
<body><header class="top"><strong>Veste+ · Administração</strong><a href="<?= site_url('admin/sair') ?>">Sair</a></header><main class="wrap"><h1>Painel administrativo</h1><p><a class="btn btn-success" href="<?= site_url('admin/exportar') ?>">Exportar relatório para Excel (CSV)</a></p><p class="muted">Visão somente para consulta. Listas limitadas aos 50 registros mais recentes.</p>
<div class="cards"><?php foreach (['doadores'=>'Doadores','beneficiarios'=>'Beneficiários','itens'=>'Itens cadastrados','interesses'=>'Interesses'] as $key=>$label): ?><div class="card"><span><?= esc($label) ?></span><strong><?= (int) $stats[$key] ?></strong></div><?php endforeach ?></div>
<section><h2>Itens doados</h2><table><thead><tr><th>#</th><th>Item</th><th>Cor</th><th>Qtd.</th><th>Status</th><th>Doador</th></tr></thead><tbody><?php foreach($itens as $row): ?><tr><td><?= (int)$row['id'] ?></td><td><?= esc($row['tipo']) ?></td><td><?= esc($row['cor'] ?? '') ?></td><td><?= (int)$row['quantidade'] ?></td><td><?= esc($row['status'] ?? 'disponível') ?></td><td><?= esc($row['nome_doador']) ?></td></tr><?php endforeach ?><?php if(!$itens): ?><tr><td colspan="6">Ainda não há itens cadastrados.</td></tr><?php endif ?></tbody></table></section>
<?php foreach (['doadores'=>'Doadores','beneficiarios'=>'Beneficiários'] as $key=>$title): ?><section><h2><?= esc($title) ?></h2><table><thead><tr><th>#</th><th>Nome</th><th>E-mail</th><th>Celular</th><th>Verificado</th></tr></thead><tbody><?php foreach($$key as $row): ?><tr><td><?= (int)$row['id'] ?></td><td><?= esc($row['nome']) ?></td><td><?= esc($row['email']) ?></td><td><?= esc($row['celular']) ?></td><td><?= $row['verificado'] ? 'Sim' : 'Não' ?></td></tr><?php endforeach ?><?php if(!$$key): ?><tr><td colspan="5">Ainda não há cadastros.</td></tr><?php endif ?></tbody></table></section><?php endforeach ?>
</main></body></html>